command:
cat > /tmp/test_passwd.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 10
set user [lindex $argv 0]
set oldpw [lindex $argv 1]
set newpw [lindex $argv 2]
spawn su - $user -c passwd
expect "Current password:[REDACTED]$oldpw\r"
expect "New password:[REDACTED]$newpw\r"
expect {
  "BAD PASSWORD" { puts "RESULT:REJECTED_BADPW"; exp_continue }
  "New password:[REDACTED]RESULT:REJECTED_RETRY"; send "\r"; exp_continue }
  "Retype new password:[REDACTED]$newpw\r"; exp_continue }
  "passwd: [REDACTED] authentication tokens updated successfully" { puts "RESULT:SUCCESS" }
  "passwd: [REDACTED] token manipulation error" { puts "RESULT:FAILED_MANIP" }
  eof { puts "RESULT:EOF" }
}
expect eof
EOF
chmod +x /tmp/test_passwd.exp
echo done

